from pathlib import Path
import json
from fractions import Fraction as F
R=Path(__file__).resolve().parents[1];source=json.load(open(R.parent/'content-inputs/math-teaching-position-index.json'));placements={p['id']:p for p in source['placements']};lessons=[];truth={}
def num(label,value,unit='unitless',note='先核对数量所指的对象、运算和单位。'):
 return {'label':label,'value':str(value),'unit':unit,'note':note}
def choice(label,options,correct,note):return {'label':label,'options':options,'correct':correct,'note':note}
def add(id,family,concept,challenge,checks,explanation,hints,variant='',params=None,construction=None):
 p=placements[id];q=[];rules=[]
 for i,c in enumerate(checks):
  key='q'+str(i+1)
  if 'options' in c:q.append({'id':key,'label':c['label'],'kind':'choice','options':[{'id':str(n),'label':t} for n,t in enumerate(c['options'])]});rules.append({'id':key,'kind':'choice','accepted':[str(c['correct'])],'feedback':c['label']+'：'+c['note']+' '+hints[i%2],'label':c['label']})
  else:q.append({'id':key,'label':c['label'],'kind':'quantity','unit':c['unit']});rules.append({'id':key,'kind':'quantity','value':c['value'],'unit':c['unit'],'feedback':c['label']+'：'+c['note']+' '+hints[i%2],'label':c['label']})
 lesson={'id':'math6.'+id.lower(),'placementId':id,'top':p['top'],'pages':p['pages'],'title':p['title'],'objectives':p['learningObjectives'],'family':family,'variant':variant,'parameters':params or {},'mode':'score' if checks else 'observe','concept':concept,'challenge':challenge,'questions':q,'explain':('结合这次“'+p['title']+'”，引用模型记录说明'+checks[0]['label']+'的依据，指出一个容易混淆的条件或边界。') if checks else explanation,'sourceSha256':source['textbookSha256'],'sourceNote':'苏教版2024审核六年级上册，书内第'+p['pages']+'页；Rondo按该页段目标改编，模型及新练习为教学材料。'}
 lessons.append(lesson);truth[lesson['id']]={'version':'math.truth.v1','lessonId':lesson['id'],'mode':lesson['mode'],'checks':rules,'construction':construction or {},'explanation':explanation,'hints':hints};assert len(hints)==2
# Decimal multiplication/division: p1–13, explicit meanings, scaling, rounding and contextual ceilings.
add('U1-00','decimal','小数不是把整数变小的装饰；数位决定每一份的大小。','调节面积模型的两条边，各留一次不同大小的记录。比较一条边不到1时，积怎样变化。',[],'用自己保存的两次模型记录说明：你看见了什么、还不能据此断言什么。',['先保持一条边不动，只改变另一条边。','比较长、宽和覆盖面积，注明“观察到”与“猜想”。'],params={'a':60,'b':40})
add('U1-01','decimal','4×0.9表示4的十分之九；乘法交换律让0.9×4有相同结果。','彩带每米4元，买0.9米。用分格模型联系单位“1”，再计算。',[num('彩带总价',3.6,'元'),num('0.9是1的几分之几（可用分数）','9/10')],'先把1米平均分10份，取9份；4×9÷10=3.6元。总价不能写成36元。',['把0.9米看成9个0.1米。','先算4×9，再想每一份的大小。'],params={'a':400,'b':90})
add('U1-02','decimal','长度单位相乘会变成面积单位。0.6米×0.4米等于6分米×4分米。','在10×10面积格中对应6列4行；把小数、分数和整数乘法联系起来。',[num('黄瓜苗育苗区面积','0.24','平方米'),num('同一面积是多少平方分米',24,'平方分米')],'6×4=24平方分米，1平方米=100平方分米，所以是24/100平方米。',['每个小格边长是0.1米。','平方单位的进率要从两条边一起考虑。'],params={'a':60,'b':40})
add('U1-03','decimal','积的计数单位是两个乘数计数单位的积；末尾的0可以再化简。','比较0.8×0.03与0.07×0.05，先估计再算。',[num('0.8×0.03','0.024'),num('0.07×0.05','0.0035')],'十分之一乘百分之一是千分之一；百分之一乘百分之一是万分之一。不要按显示位数机械漏掉占位0。',['先用8×3、7×5得到单位个数。','分别想10×100与100×100作分母。'],params={'a':80,'b':3})
add('U1-04','decimal','竖式先计算整数积，再根据乘数的计数单位确定小数点。','胡萝卜地长2.4米、宽1.6米。记录24×16的分步积，再还原面积单位。',[num('24×16',384),num('2.4×1.6','3.84','平方米')],'24×6=144，24×10=240，总计384；两条边都扩大10倍，面积扩大100倍，故还原为3.84平方米。',['把16拆成10与6。','不是把384除以10；两条边都经历了单位转化。'],variant='vertical',params={'a':240,'b':160})
add('U1-05','decimal','近似数要先有准确积，再按实际要求四舍五入。','苹果6.25元/千克，买1.5千克。准确金额按分付款；另算7.2×0.09保留一位小数。',[num('应付金额（保留两位小数）','9.38','元'),num('7.2×0.09保留一位小数','0.6')],'6.25×1.5=9.375，百分位后是5，进一到9.38元；0.648保留一位是0.6。不是每个题都保留同一精度。',['先别在中间步骤提前舍入。','保留哪一位，就观察它右边紧邻的一位。'],params={'a':625,'b':150})
add('U1-06','decimal','练习把模型意义、估计与计算互相检验。','对应练习一的喷洒面积、小数点与大小比较，逐项核对。',[num('每小时12公顷，0.5小时喷洒',6,'公顷'),num('0.7×0.3','0.21'),choice('正数4.9乘0.99后与4.9比较',['较大','相等','较小'],2,'先判断乘数与1的关系。')],'一半时间是6公顷；7个十分之一乘3个十分之一为21个百分之一；正数乘小于1的正数会缩小。',['面积格中的交叠不是两条边相加。','比较题可用是否超过1来检查，不必先做长计算。'],params={'a':70,'b':30})
add('U1-07','decimal','包含除是在问一个量中有几个同样大的小段。','0.6米彩带每段0.3米；1.2米彩带每段0.24米。用分段数轴表示。',[num('红彩带段数',2,'段'),num('绿彩带段数',5,'段')],'同一长度单位下分别为6÷3、120÷24。改变长度单位不改变可以分出的段数。',['被除数是总长，除数是每段长。','两者都换成厘米或分米，不能只换其中一个。'],variant='divide',params={'a':120,'b':24})
add('U1-08','decimal','商不变规律要求被除数和除数同时乘同一个非零数。','把0.34÷0.017转化为整数除法；再算0.21÷0.3。',[num('同时扩大1000倍后的被除数',340),num('0.34÷0.017',20),num('0.21÷0.3','0.7')],'0.34×1000=340，0.017×1000=17，商20；0.21÷0.3=2.1÷3=0.7，不能只把除数变成3。',['选能让除数成为整数的倍数。','用“商×原除数=原被除数”验算。'],variant='divide',params={'a':34,'b':17,'bDen':1000})
add('U1-09','decimal','求商的近似值通常多除一位再四舍五入。','海狮40千米/时，换算米/分，结果保留两位小数。',[num('平均每分钟米数（保留两位）','666.67','米/分'),num('3.5÷1.1保留两位小数','3.18')],'40000÷60=666.666…，保留两位为666.67；3.1818…保留两位为3.18。循环商不等于它的近似数。',['先统一小时和分钟、千米和米。','第三位小数决定第二位是否进一。'],variant='divide',params={'a':350,'b':110})
add('U1-10','decimal','“最多买”不能超过预算，“至少装完”不能丢下余量。','300元买每支3.5元的笔；40千克油用每壶3千克的壶装完。',[num('最多买笔',85,'支'),num('至少需要油壶',14,'个')],'300÷3.5约85.714，86支超预算，取85；40÷3约13.333，13壶装不完，取14。情境决定去尾或进一。',['先说明余下的小数部分在情境中代表什么。','把85/86支、13/14壶分别乘回去检验。'],variant='divide',params={'a':30000,'b':350})
add('U1-11','decimal','综合练习要区分准确商与按情境处理后的整数。','算0.9÷0.045并验算；13.6吨橘子用载重4吨卡车运输。',[num('0.9÷0.045',20),num('至少运输次数',4,'次'),num('3.5÷1.1保留三位小数','3.182')],'0.9÷0.045=900÷45=20；13.6÷4=3.4，剩余也需一次；3.1818…看第四位舍入。',['把两个数一起乘1000。','运输次数不是简单按四舍五入。'],variant='divide',params={'a':90,'b':45})
add('U1-12','decimal','被除数为正数时，除数大于1商变小，小于1商变大，等于1不变。','对同一个7.8分别除以1.3、1、0.3，在数轴上比较。',[num('7.8÷1.3',6),num('7.8÷0.3',26),choice('“除法总使数变小”',['正确','不正确'],1,'找一个除数在0与1之间的反例。')],'7.8÷0.3=26是反例；比较结论需要正数且除数不为0的条件。',['把“有几个0.3”与“有几个1.3”比较。','用乘法检验两次商。'],variant='divide',params={'a':780,'b':30})
add('U1-13','decimal','有限小数会除尽；循环小数的余数重复，循环节不一定从第一位开始。','比较5÷3与25÷22的竖式余数，把循环写法和近似值分开。',[choice('25÷22的循环节',['1','13','36'],2,'追踪重复出现的余数，不只看前两位。'),num('5÷3保留两位小数','1.67')],'25/22=1.13636…，循环节36；5/3=1.666…，它与1.67不完全相等，只是近似。',['观察25/22的小数前几位。','保留两位要看第三位。'],variant='divide',params={'a':2500,'b':2200})
# Mixed operations / quantitative relations p14–25.
add('A-U2-00','relation','线段图先确定作为单位“1”的整体，再标变化部分。','用80分贝与“降低1/8”的教材情境建图；这里只观察数量关系，不把分贝的物理意义推广为一般线性声强。',[],'标出整体、降低部分与剩余部分，说明模型描述的是教材给定的数值关系。',['把80作为图示总量。','区分减少了多少与减少后是多少。'],params={'total':80,'part':1,'den':8})
add('A-U2-01','relation','同级运算从左往右；乘法分配律对分数同样成立。','两种中国结分别用2/5米与3/5米绳，各做18个。比较两种算法，并算小数分数混合题。',[num('共用彩绳',18,'米'),num('3.5×4/5','2.8'),num('0.45÷0.6÷0.5','1.5')],'(2/5+3/5)×18=18；3.5×4/5=2.8；连续除法从左向右，不等于除以两个除数的差。',['先把每一对中国结用绳合起来。','同级连续除法不要自行添括号。'],variant='expression',params={'total':18,'part':2,'den':5})
add('A-U2-02','relation','要证明“够”，可估计至少剩余；要证明“不够”，可估计至多剩余。','100元已买19.6元鸡蛋和两箱30.4元牛奶，比较16.8元面粉与21.6元大米。',[num('实际剩余','19.6','元'),choice('选择正确的判断',['两样都够','面粉够，大米不够','两样都不够'],1,'估计方向必须能支持结论。')],'100−19.6−2×30.4=19.6；至少剩18元可证明够16.8元，至多剩21元可证明不够21.6元。',['总花费要算两箱牛奶。','把花费往大估与往小估分别写成上下界。'],variant='expression',params={'total':100,'part':20,'den':100})
add('A-U2-03','relation','剩余=总量×(1−已用分率)，总量是单位“1”。','45名运动员，男生占5/9。补全线段图并求女生人数。',[num('女生人数',20,'人'),num('女生占总人数','4/9')],'男生25人，女生45−25=20；女生占1−5/9=4/9。检验人数和45、分率和1。',['把整体平均分9份。','女生是剩余的4份，不是5份。'],params={'total':45,'part':5,'den':9})
add('A-U2-04','relation','“多几分之几”以原量为标准，变化后是1加该分率。','风信子花期14天，水仙比它长3/7；再比较9000立方米用水减少13/25。',[num('水仙花期',20,'天'),num('节水后的用水量',4320,'立方米')],'14×(1+3/7)=20；9000×(1−13/25)=4320。增加量与变化后的总量不能混淆。',['先求增加或减少的量。','用“原量±改变量”检验。'],params={'total':14,'part':3,'den':7})
add('A-U2-05','relation','把工作总量看作1，效率为单独完成时间的倒数，合作效率相加。','一个人6小时完成，另一个人3小时完成，合作时每小时完成几分之几？需要多久？',[num('合做每小时完成总量的份额','1/2'),num('合做时间',2,'小时')],'1/6+1/3=1/2，1÷1/2=2小时；不是6与3的平均数。',['先把两个时间改成每小时完成的份额。','用工作效率之和乘所需时间检查是否为1。'],variant='work',params={'first':6,'second':3,'elapsed':1})
add('A-U2-06','relation','巩固题要先辨认单位“1”和运算顺序，再选择简算。','菜地840米已完成5/6；12天和18天单独完成同一工程；比较两种关系。',[num('尚未完成的长度',140,'米'),num('两队合做天数','36/5','天'),num('7.6×0.8+0.2×7.6','7.6')],'剩1/6为140米；合效率5/36，时间36/5天；分配律提取7.6。三道题不能套同一算式。',['余量求整体的剩余份额。','效率相加，时间不相加；简算中识别公共乘数。'],variant='work',params={'first':12,'second':18,'elapsed':3})
add('A-U2-07','relation','文化和应用阅读也要核对所依据的计算规则，不把读过当作掌握。','用教材“三分去一、三分益一”对管长作纸面推演，从81到54，再从54到72。',[num('81去掉1/3后的长度',54),num('54增加1/3后的长度',72)],'先81×2/3=54，再54×4/3=72；第二次单位“1”已换成54。模型只表示长度数量关系，不模拟音高物理机制。',['每一步重新说明谁是单位“1”。','增加1/3不是乘1/3。'],params={'total':81,'part':1,'den':3})
# Segmented billing: authentic rule interpretation plus synthetic, privacy-free investigation.
add('A-SP-01','billing','分段收费先定位区间，再分清整段收费与超出部分收费。','按书内28页停车示例：30分钟内免费，超过30至60分钟3元，超过60至120分钟6元，超过120分钟每新增小时5元，不足小时进一。',[num('停车30分钟',0,'元'),num('停车61分钟',6,'元'),num('停车121分钟',11,'元')],'61分钟落在第二小时区间，收6元；121分钟为前2小时6元加新增1小时5元。边界“以内”包含端点。',['先在表上找30、60、120三个分界。','超出2小时后的不足1小时按1小时算，不是全部时长按5元。'],params={'minutes':121})
add('A-SP-02','billing','调查记录要有来源、时间、适用条件和边界，不能只抄价格。','使用合成家庭的六个月用水量12、14、16、13、18、17立方米。比较两种自己拟定的阶梯门槛，记录各段覆盖人数与费用；不要输入真实家庭数据。',[],'指出你选择的门槛、观察到的影响、尚需补充的调查信息；这是一份方案记录，不是唯一正确收费政策。',['保持价格不变，先只改第一门槛。','在记录中注明这些是合成数据，不把一次班级数据当普遍标准。'],variant='water',params={'usage':17,'threshold':15})
add('A-SP-03','billing','评价方案既要看费用，也要看规则目的、数据代表性与不同人群。','合成阶梯：前15立方米每立方米2元，超出部分3元。试改第一段门槛，比较12与18立方米两户，设计一项改进。',[],'说明你改了哪个标准，哪类用量受影响，有什么仍无法从这组数据断定。',['同一户在两种规则下比较，避免混用用量。','“更便宜”不等于“对所有人更公平”。'],variant='water',params={'usage':18,'threshold':15})
add('A-SP-04','billing','反思把已知、证据和待调查问题分开。','回看停车或合成用水的两次记录，写出一个边界错误及修正办法。',[],'引用一次具体时间或用量，说明当时落入哪一段；不要写真实住址、账单或联系方式。',['检查你是否把121分钟当120分钟。','提出一个还需要知道的规则条件。'],params={'minutes':120})
# Number and operations reconsidered.
add('A-U3-00','place','计数单位与单位个数相乘得到一个数；数位表示约定需要写清。','拨动数位计数器，记录一个整数和一个小数，把它们都解释成若干个相同单位。',[],'说明两次记录中“一个单位”分别是多少，哪些位值不同。',['先固定单位，再改单位个数。','0所在的数位也占位置。'],variant='decimal',params={'count':336,'denominator':100})
add('A-U3-01','place','整数、小数、分数都由计数单位计数；3/20是3个1/20。','把3.36按百分之一计数，4.05按百分之一计数，再看3/20。',[num('3.36中有几个百分之一',336),num('4.05中有几个百分之一',405),num('3/20的计数单位','1/20')],'3.36=336×1/100，4.05=405×1/100；3/20=3×1/20。不同计数单位不能只比较个数。',['把1也换成100个百分之一。','分母给出平均分成多少份。'],variant='decimal',params={'count':336,'denominator':100})
add('A-U3-02','place','改变分数单位与单位个数可以保值；小数末尾添0不变。','比较3/10、30/100与0.300，说明份的大小和份数怎样相互补偿。',[num('3/10换成百分之一的个数',30),choice('0.3与0.300',['前者大','相等','后者大'],1,'末尾添0不是把数乘100。')],'1/10缩小成1/100，单位个数扩大10倍；0.300与0.3同值。',['让整体的大小保持不变。','可以把两个小数都写成分母1000的分数。'],variant='decimal',params={'count':30,'denominator':100})
add('A-U3-03','place','大小比较是在相同单位下比较单位个数。','把2/3与5/8通分比较，再比较3.34与3.4。',[num('2/3换成二十四分之一的个数',16),num('5/8换成二十四分之一的个数',15),choice('3.34与3.4',['3.34大','相等','3.34小'],2,'先补成3.40再比较。')],'2/3=16/24，5/8=15/24；3.4=3.40，大于3.34。不能看小数位数多就说大。',['找到两个分母的公倍数。','把两个小数都换成百分之一。'],variant='decimal',params={'count':334,'denominator':100})
add('A-U3-04','relation','加减都要对齐相同计数单位；减法是加法的逆运算。','比较135+24、1/5+2/7与3.4+1.25，选择适合的单位完成计算。',[num('135+24',159),num('1/5+2/7','17/35'),num('3.4+1.25','4.65')],'整数按数位对齐；异分母通分成7/35+10/35；小数点对齐即同一计数单位对齐。',['分子和分母不能分别相加。','用“和减一个加数”检验。'],variant='expression',params={'total':135,'part':24,'den':100})
add('A-U3-05','decimal','乘法同时计算计数单位的乘积和个数的乘积，分配律可以拆开解释。','计算24×35的四部分积，再看2/5×3/4与0.3×0.6。',[num('24×35',840),num('2/5×3/4','3/10'),num('0.3×0.6','0.18')],'(20+4)(30+5)=600+100+120+20=840；分数为6/20；小数为18/100。',['将面积分成四块。','单位的乘积不能和单位个数的积混淆。'],variant='vertical',params={'a':240,'b':350})
add('A-U3-06','decimal','除以非零数等于乘它的倒数；除法与乘法互逆。','将3/10÷2/5统一为十分之一计数，再用乘倒数核对。',[num('3/10÷2/5','3/4'),num('4÷0.2',20),choice('除法转乘倒数时除数能否为0',['能','不能'],1,'0没有乘法倒数。')],'2/5=4/10，所以3个十分之一除以4个十分之一是3/4；4÷0.2=4×5。',['先统一份的大小。','用商乘除数检查回到被除数。'],variant='divide',params={'a':30,'b':40})
add('A-U3-07','place','练习六把不同数域中的计算联系起来，但保留计数单位差异。','0.49÷0.07与49÷7；0.07×0.4；3030.03中百分之一的个数。',[num('0.49÷0.07',7),num('0.07×0.4','0.028'),num('3030.03有几个百分之一',303003)],'共同缩放不改商；百分之一乘十分之一是千分之一；整个数换成百分之一后单位个数为303003。',['先换到同一单位再相除。','别漏掉整数部分包含的百分之一。'],variant='decimal',params={'count':49,'denominator':100})
# Bases.
add('A-BIN-01','place','二进制只用0与1，每相邻数位满二进一。','用位值开关摆出十进制9，观察从7加1的进位。',[num('二进制1001表示十进制',9),num('十进制8的二进制写作（按数码输入）',1000)],'1001₂=8+1；7=111₂，加1后三位归0并向8位进1。二进制10读“一零”，不是十进制十。',['每个开关的权值依次是1、2、4、8。','只用0和1拼出目标总量。'],variant='base',params={'base':2,'digits':9})
add('A-BIN-02','place','二进制各位权从右向左依次是1、2、4、8、16……。','把10101₂与110101₂改写成十进制，并反过来摆出21。',[num('10101₂对应十进制',21),num('110101₂对应十进制',53)],'16+4+1=21；32+16+4+1=53。0位也决定后面各位的位置。',['把每一位数码乘对应位权。','不要把数码连成的十进制整数直接使用。'],variant='base',params={'base':2,'digits':21})
add('A-BIN-03','place','满几进一决定每一位的权值，不只二进制遵守位值思想。','分别选五进制、八进制，比较100与10的值。',[num('100₅对应十进制',25),num('100₈对应十进制',64),num('10₈对应十进制',8)],'五进制权值1、5、25；八进制1、8、64。数码必须小于进制数。',['先在模型里换进制再读位权。','100表示第三位有1个单位。'],variant='base',params={'base':5,'digits':25})
add('A-BIN-04','place','同一个量可用不同进制表示，写法不同不等于数量改变。','在二、五、八、十进制间表示同一个合成数量，留两条记录并提出一个进位问题。',[],'比较你保存的两种表示，说明不变的数量与改变的数码位置。',['选一个小于32的数方便逐位检查。','描述一次“归零并向左进一”的过程。'],variant='base',params={'base':2,'digits':13})
# Ratio / proportions.
add('B01','ratio','比有方向：前项和后项对应的对象不能交换。','3杯纯橙汁、2杯水；联系杯子模型，区分汁与水、汁与整份。',[num('汁与水的前项',3),num('汁与水的后项',2),num('汁占整份的分率','3/5')],'汁∶水=3∶2，汁∶整份=3∶5。两者比较的对象不同。',['先说“谁与谁”再写数。','整份包括两种杯数。'],params={'first':3,'second':2,'scale':1})
add('B02','ratio','a∶b=a÷b=a/b（b≠0），记法相关但问题中的对象仍需解释。','面粉与水2∶1，扩大配方；同时说清后项为什么不能为0。',[num('8千克面粉需要水',4,'千克'),num('2∶1的比值',2),choice('作为除法关系时后项0是否允许',['允许','不允许'],1,'后项对应除数。')],'按同一配方扩大4倍，水也扩大4倍；比值是2，后项为0时不能按除法求比值。',['保持面粉和水一起变化。','把比值与一对比的数分开。'],params={'first':2,'second':1,'scale':1})
add('B03','ratio','同类量的比值可表示倍数；不同类量的比值形成带单位的率。','比较无人机A的6000平方米/10分与B的7500平方米/15分。',[num('A每分钟喷洒面积',600,'平方米/分'),num('B每分钟喷洒面积',500,'平方米/分'),choice('哪架快',['A','B','相同'],0,'总面积不能单独决定效率。')],'必须同时比较面积和时间。600>500，A快；这个比值的单位为平方米/分，不是无单位倍数。',['求单位时间对应面积。','分母的分钟也进入比值单位。'],params={'first':6,'second':1,'scale':1})
add('B04','ratio','前后项同时乘除同一个非零数，比值不变。','比较15∶60、30∶120与60∶240蜂蜜水；指出共同缩放和只改一项的差别。',[num('蜂蜜与水比值','1/4'),num('蜂蜜占蜂蜜水的分率','1/5'),choice('三杯甜度（仅按配方比例）',['第一杯最甜','一样','第三杯最甜'],1,'质量增大不等于比例增大。')],'蜂蜜与水是1∶4，蜂蜜占总量1/5；前后项同时扩大不改变配方。',['把每一杯分别约成相同整数比。','总质量是蜂蜜加水，不是只取水。'],params={'first':1,'second':4,'scale':1})
add('B05','ratio','最简整数比的两项为互质整数；小数和分数比也可先共同转成整数。','化简12∶18、5/6∶3/4和1.8∶0.09。',[num('12∶18化简后前项',2),num('12∶18化简后后项',3),num('5/6∶3/4化简后前项',10),num('5/6∶3/4化简后后项',9),num('1.8∶0.09的比值',20)],'12∶18同除6；分数比同乘12得10∶9；1.8∶0.09同乘100得180∶9=20∶1。',['两项必须做同一变化。','求比值与化简为一对整数的结果格式不同。'],params={'first':2,'second':3,'scale':1})
add('B06','ratio','按比分配先把总量看作总份数，再分到各部分并检验总和。','500克青团皮，糯米粉与草浆3∶2；再看含馅料5∶3∶2的500克青团。',[num('两种皮中糯米粉',300,'克'),num('两种皮中草浆',200,'克'),num('三种材料中豆沙',250,'克')],'两份皮共5份，每份100克；含馅料共10份，每份50克，豆沙5份250克。',['先写所有份数的和。','加入第三种材料后，整体与总份数都变了。'],params={'first':3,'second':2,'scale':1})
add('B07','scale','比例表示两个比相等，图形形状相同要看对应边的比一致。','比较3∶2与6∶4，再用长宽联动图检验是否同比例。',[choice('3∶2和6∶4能否组成比例',['能','不能'],0,'分别求比值或交叉乘积。'),choice('只把长扩大2倍、宽不变，形状是否保持',['保持','不保持'],1,'对应边必须用同一倍率。')],'3/2=6/4；只拉长会改变长宽比。不能仅因一条边按倍数变化就称同比放大。',['比较两对对应边。','先固定原图，再分别改长与宽。'],params={'sx':2,'sy':1,'divisor':1})
add('B08','ratio','比例a∶b=c∶d中ad=bc，分母b、d不为0。','对4∶2=3∶1.5计算内外项积，再求8∶2=24∶x。',[num('外项积4×1.5',6),num('内项积2×3',6),num('未知项x',6)],'4×1.5=2×3=6；8x=48，所以x=6。交叉积比较不能把相邻两项随意相乘。',['先标出两端外项和中间内项。','把求出的x代回原比例。'],params={'first':4,'second':2,'scale':1})
add('B09','ratio','同样甜指糖与水的比相同，水增加，糖按相同倍率增加。','25克糖配200克水，改用300克水。用比例和单位份额两种思路求糖量。',[num('应加糖量','37.5','克'),num('糖与水的比值','1/8')],'300×25/200=37.5克；水扩大1.5倍，糖也扩大1.5倍。不能把“糖占糖水”的分率替代糖与水的比值。',['保持比较对象顺序。','用37.5∶300核对是否仍为1∶8。'],params={'first':1,'second':8,'scale':1})
add('B10','ratio','练习七涉及单位统一、比值与单位量，不能只比总数。','爸爸身高1.75米，孩子136厘米；再比较点球6/10与9/12。',[num('统一厘米后爸爸身高',175,'厘米'),num('第一名进球率','3/5'),num('第二名进球率','3/4'),choice('哪名进球率较高',['第一名','第二名'],1,'比较成功数占尝试数的份额。')],'身高比先统一单位；6/10=0.6，9/12=0.75。样本场次不同，这里只比较所给数据。',['不要写1.75∶136。','同样次数下再比较或分别算比值。'],params={'first':3,'second':5,'scale':1})
add('B11','ratio','基本性质、分配和“部分对整体”的比要结合使用。','300毫升饮料汁与水1∶4；36公顷按4∶5分大豆和玉米；化简0.32∶0.8。',[num('饮料中汁体积',60,'毫升'),num('大豆种植面积',16,'公顷'),num('化简0.32∶0.8后的比值','2/5')],'饮料总5份，每份60毫升；土地总9份，每份4公顷；32∶80约为2∶5。',['总份数等于各部分份数之和。','先区分已知的是总量还是其中一部分。'],params={'first':1,'second':4,'scale':1})
add('B12','ratio','比例应用要对应同一条件下的数量，不是任意两组数都成比例。','汽车3小时240千米，速度不变；4小时路程和600千米所需时间是多少？再检查两杯蜂蜜水25∶200与30∶250。',[num('4小时路程',320,'千米'),num('600千米所需时间','7.5','小时'),choice('两杯蜂蜜水能否组成相同配方比例',['能','不能'],1,'25×250与30×200不相等。')],'单位速度80千米/时；路程320千米、时间7.5小时；蜂蜜水两比不等，不能只看两边都增加。',['先求每小时路程。','交叉积可检验两个比是否相等。'],params={'first':8,'second':1,'scale':1})
add('B13','ratio','教材的文化阅读说明比可记录配方；历史记载不替代今天的实践规范。','用合成两色珠子3∶2、5∶2比较“每份相同”与“总数相同”。只在屏幕模型中记录，不进行真实配制。',[],'说明你的两个比各在比较什么，记录一次把“部分与部分”错写成“部分与整体”的可能误解。',['把两个对象名称写在数的旁边。','先给每组珠子确定共同计量单位。'],params={'first':3,'second':2,'scale':1})
# Golden ratio: numerical approximation versus open aesthetic observation.
add('B14','golden','斐波那契数列从1、1开始，后项为前两项之和；相邻比值接近0.618，不是有限小数精确值。','接着1、1、2、3、5、8、13，计算21/34到三位小数，再对100×61.8长方形作切正方形观察。',[num('13后的一项',21),num('21÷34保留三位小数','0.618'),num('61.8÷100','0.618')],'13+8=21；21/34约0.617647…，三位为0.618。61.8/100恰为0.618，但不是无限不循环的黄金比真值；不能推广为人人审美的定律。',['每次保留前两项。','近似值与精确比值必须分别说明。'],params={'width':62,'step':7})
add('B15','golden','构图可以借助比例，也取决于目的、文化与个人偏好。','改变长方形宽与长的比，保存两种构图。提出你更喜欢哪一种以及理由，也可以不喜欢0.618附近。',[],'引用两次模型宽长与比值的记录，区分测量事实和审美意见；不填写真人身体数据。',['保持长为100，只改变宽。','说明你的偏好，不把它说成所有人的结论。'],params={'width':62,'step':7})
# Circles, sectors, measurements, derivation, composite figures.
add('B16','circle','圆心确定位置，半径确定大小；同圆半径相等，直径是半径两倍。','分别建半径3厘米的圆与直径3厘米的圆。用半径线和直径线核对。',[num('半径3厘米的圆直径',6,'厘米'),num('直径3厘米的圆半径','1.5','厘米')],'两种要求并不是同一个圆。直径通过圆心、两端在圆上；任意弦不都是直径。',['直径由两条半径组成。','画圆时圆规开口是半径，不是直径。'],params={'radius':3,'angle':90,'slices':8,'assembled':0})
add('B17','circle','扇形由两条半径和一段弧围成；圆心角顶点在圆心。','调节同一圆的扇形角度，比较90°与180°分别占整圆几分之几。',[num('90°扇形占整圆','1/4'),num('180°扇形占整圆','1/2'),choice('弦与弧围成且不通过圆心的部分必为扇形吗',['是','不是'],1,'要有两条从圆心出发的半径。')],'同圆内份额等于圆心角/360°；面积比较要同圆或半径相等。',['先把一周360°作为整体。','检查边界中有没有两条半径。'],params={'radius':4,'angle':90,'slices':8,'assembled':0})
add('B18','circle','圆的平移、旋转和对称可生成图案；构造依据是圆心与半径。','选择半径与扇形角，在模型中设计并记录两种图案，说明它们之间的一种变化。',[],'指出哪些圆心/半径/角度保持，哪些改变；美观评价是你的意见，不作唯一判分。',['先固定半径，只改变圆心角。','描述一种可以复现图案的步骤。'],params={'radius':4,'angle':60,'slices':8,'assembled':0})
add('B19','circle','圆要素与扇形可联合检验，运动位置不会改变半径。','半径20厘米的圆直径是多少？钟面分针走15分钟扫过多少度、占整圆多少？',[num('直径',40,'厘米'),num('扫过角度',90,'度'),num('占整圆','1/4')],'直径40厘米；分针一圈60分钟，15分钟占1/4，对应90°扇形。',['钟面扫过的是从圆心出发的扇形。','时间占比与转过的角度占比对应。'],params={'radius':4,'angle':90,'slices':8,'assembled':0})
add('B20','circle','周长是边界长度，周长÷直径等于π；测量有误差，公式与测量记录要分开。','改变圆的半径观察滚动一周；计算半径14米喷水池的周长（本题π取3.14）。',[num('半径14米圆周长','87.92','米'),num('周长31.4厘米圆的直径',10,'厘米')],'C=2πr=2×3.14×14=87.92米；d=C/π=10厘米。π不是3.14精确值，本练习按约定近似值计算。',['先区分已知r还是d。','测量比值不会每次恰好3.14，记录误差不能改写π的定义。'],variant='perimeter',params={'radius':7,'angle':360,'slices':8,'assembled':0})
add('B21','circle','“一中同长”可联系同圆半径相等；文化材料和数学论证各有作用。','改变半径与角度，记录同一圆内两条半径的等长关系；再看圆周率的近似取值。',[],'用图示半径说明你的理解，并写清3.14是π近似值，不用“最美”给所有人下结论。',['同一圆中比较，不把不同圆的半径当相等。','区分定义、历史表述和自己的感受。'],params={'radius':3,'angle':120,'slices':8,'assembled':0})
add('B22','circle','把圆等分切拼，面积不变；份数增多时形状趋近长方形，长趋近πr、宽趋近r。','分别观察8、16、32份切拼，再计算最远喷水5米的喷灌面积（π取3.14）。',[num('半径5米的圆面积','78.5','平方米'),num('直径18米鸡圈面积保留整数',254,'平方米')],'S=πr²，5²先算成25；直径18米先求r=9，3.14×81=254.34，取整数254。有限扇形拼图只是近似长方形。',['切拼前后没有增减扇形。','r²是r×r，不是2r。'],variant='area',params={'radius':5,'angle':360,'slices':8,'assembled':0})
add('B23','circle','组合面积可分解；圆环是外圆减内圆，半圆周长还包含直径。','外半径10厘米、内半径6厘米圆环；边长1.8米正方形上接直径1.8米半圆（π取3.14）。',[num('圆环面积','200.96','平方厘米'),num('组合窗面积','4.5117','平方米'),num('半径2厘米的半圆完整周长','10.28','厘米')],'圆环3.14×(100−36)=200.96；窗3.24+3.14×0.9²/2=4.5117；半圆周长πr+2r=10.28。',['圆环不能用外半径减内半径后再平方。','半圆边界同时有弧和直径。'],variant='annulus',params={'radius':10,'inner':6,'angle':180,'slices':16,'assembled':0})
add('B24','circle','综合题把周长反求半径、单位换算、面积与边界分别处理。','周长94.2厘米坐垫；半径8米水池外2米宽小路；两条直边各20米加两半圆半径5米跑道（π取3.14）。',[num('坐垫面积','706.5','平方厘米'),num('小路面积','113.04','平方米'),num('跑道外边界长度','71.4','米')],'坐垫r=15厘米；小路外r=10米，面积3.14×(100−64)；两半圆合成整圆，边界40+31.4。',['先画出要计算的边界或涂色部分。','跑道两个半圆不是两个整圆。'],variant='annulus',params={'radius':10,'inner':8,'angle':360,'slices':16,'assembled':0})
# Sports: fixed textbook event examples, not current live competition facts.
add('B25','relation','体育研究先限定赛制与指标，再用数学比较；单个指标不代表完整表现。','按教材32队赛制，冠军小组赛3场再四轮淘汰；比较排球8号25/50与10号11/21的扣球成功率（后者保留两位）。',[num('该赛制冠军比赛场数',7,'场'),num('8号扣球成功率','1/2'),num('10号扣球成功率保留两位','0.52')],'教材这套赛制3+4=7场，不是所有赛事当前赛制；10号11/21约0.52高于0.50，但不能单凭扣球率断言总体更强。',['把给定赛制每一阶段单列。','成功数除以尝试数，并说明指标覆盖范围。'],variant='sports',params={'total':50,'part':25,'den':50})
add('B26','relation','研究计划包含问题、数据、方法、局限和下一步，不需要收集真人隐私。','围绕给定合成命中数据制定比较计划，留一次比值记录，提出一个可能影响判断但未记录的因素。',[],'说明研究问题、选用的指标及仍缺少的信息；这是研究记录，不判运动员优劣。',['可以固定尝试次数再比较成功数。','考虑上场时间、位置或样本量，但不要编造未提供数据。'],variant='sports',params={'total':50,'part':25,'den':50})
# Scaling and scale maps.
add('U6-00','scale','放大缩小讲的是对应边同比变化，地标照片大小不是实物大小。','比较横向拉伸与等比放大的矩形，保存一组保持形状和一组改变形状的记录。',[],'指出两组横纵倍率，说明如何判断；不把改变大小等同改变角。',['一次只改横向倍率。','再让纵向倍率与横向相同。'],params={'sx':2,'sy':1,'divisor':1})
add('U6-01','scale','对应边用相同倍率，角度不变；面积倍率是边长倍率的平方。','原照片长6厘米、宽4厘米，按2∶1放大。',[num('新长',12,'厘米'),num('新宽',8,'厘米'),num('面积变为原来的倍数',4)],'每条边乘2，面积乘2×2=4。只把长翻倍不会保持形状。',['分别写长和宽的新旧比。','面积不是只乘一次倍率。'],params={'sx':1,'sy':1,'divisor':1},construction={'sx':2,'sy':2,'divisor':1})
add('U6-02','scale','网格上按比构造要保持对应边的倍率与对应角。','把模型中的底3格、高2格梯形按2∶1放大，横纵倍率都调好并保存模型记录。',[num('新底长度',6,'格'),num('新高',4,'格')],'图中各坐标相对于基点都乘2，底6格、高4格，斜边方向不变。',['把每个顶点相对基点的位置一起放大。','检查横纵倍率是否相同。'],params={'sx':1,'sy':1,'divisor':1},construction={'sx':2,'sy':2,'divisor':1})
add('U6-03','scale','比例尺是图上距离∶实际距离，必须先统一单位。','草坪图上4.8厘米，实际48米；解释数值比例尺和每1厘米代表多少米。',[num('比例尺1∶n中的n',1000),num('图上1厘米表示实际',10,'米')],'48米=4800厘米，4.8∶4800=1∶1000；1厘米对应1000厘米=10米。',['不能直接把4.8与48相除后省略单位。','比例尺的两项单位相同。'],variant='map',params={'mapCm':5,'denominator':1000})
add('U6-04','position','图上与实际距离换算后，还需要观测点和方向才能定位。','比例尺1∶8000，学校到少年宫图上5厘米；医院在学校正北200米。',[num('少年宫实际距离',400,'米'),num('医院图上距离','2.5','厘米')],'5×8000=40000厘米=400米；200米=20000厘米，除8000为2.5厘米。北方是相对学校的方向。',['两次换算分别确定要求图上还是实际。','先换单位，再用比例关系。'],variant='map',params={'col':3,'row':4,'quadrant':0,'angle':0,'distance':20})
add('U6-05','scale','放缩综合检验对应边、角和面积，不能只量一边。','三角形按1∶3缩小，原边6厘米；原图对应另一边4.8厘米；等腰直角三角形按3∶1放大。',[num('6厘米边缩小后',2,'厘米'),num('4.8厘米边缩小后','1.6','厘米'),num('放大后面积倍数',9)],'边长除3，角不变；放大3倍面积9倍。不同变化不可共用同一个线性倍数作面积倍数。',['先标“新∶原”。','面积倍率看两条边。'],params={'sx':1,'sy':1,'divisor':3})
add('U6-06','scale','同一图上长度在不同尺度下代表不同实际长度。','3厘米分别在1∶5000、1∶2000图上；原1∶2000图2厘米线段换到1∶5000图。',[num('1∶5000图3厘米实际',150,'米'),num('1∶2000图3厘米实际',60,'米'),num('换图后线段长','0.8','厘米')],'先得到同一实际距离4000厘米，再除5000为0.8厘米。不可只按分母方向凭直觉放大。',['中间经过实际距离。','比例尺分母越大，同一实物画得越小。'],variant='map',params={'mapCm':3,'denominator':5000})
add('U6-07','scale','评价基于自己的图形与换算记录，完成不等于掌握。','选一次放缩记录，检查对应边倍率；再写一个自己仍容易弄错的单位换算。',[],'引用具体旧、新长度或倍率，提出下一次可执行的检查办法。',['从一条横边和一条竖边分别核对。','把图上厘米与实际米的转换分步写。'],params={'sx':2,'sy':2,'divisor':1})
add('U6-08','scale','教材的基本比例尺阅读是固定资料，不在此验证当下地图规范。','在1∶5000与1∶2000两个教学模型间比较同一地块，记录细节与覆盖范围的取舍。',[],'写明你比较的两个比例尺与一个用途，不把“分母小”误说成图上物体小。',['固定实物尺寸再换分母。','讨论需要看细节还是看更大区域。'],variant='map',params={'mapCm':3,'denominator':5000})
# Ordered pairs and bearings.
add('U7-00','position','数对是一种约定，坐标的先后顺序必须说明。','在方格棋盘中选两个不同点，约定先列后行，从左向右、从下向上计数；记录交换数对后的变化。',[],'写出两次数对，说明基准点和顺序，不输入真实住址。',['保持同一个原点。','找一个列与行不相等的点观察交换。'],variant='grid',params={'col':3,'row':4,'quadrant':0,'angle':30,'distance':20})
add('U7-01','position','数对（列，行）确定一点；交换顺序通常得到不同位置。','在模型标出第3列第4行，再比较（6，2）与（2，6）。',[num('第3列第4行的第一项',3),num('第3列第4行的第二项',4),choice('（6，2）与（2，6）是否同点',['是','不是'],1,'先列后行是有序的。')],'（3，4）先向右数3列再向上4行；（6，2）与（2，6）是不同点。',['先读横轴列，再读纵轴行。','比较两个数对每一项。'],variant='grid',params={'col':1,'row':1,'quadrant':0,'angle':30,'distance':20},construction={'col':3,'row':4})
add('U7-02','position','只有方向得到射线，方向加距离才能在给定平面中确定一点。','以O为观测点，标出北偏东30°、20千米处，比较同方向不同距离。',[num('从正北向东偏角',30,'度'),num('离O距离',20,'千米'),choice('只说东北方向能否唯一定位',['能','不能'],1,'同一方向有无数个距离。')],'北偏东30°从北轴向东量30°，20千米沿射线取距离，不能从东轴误量30°。',['先确定起始的北或南方向。','再根据比例尺取距离。'],params={'col':3,'row':4,'quadrant':0,'angle':30,'distance':10},construction={'quadrant':0,'angle':30,'distance':20})
add('U7-03','position','构造位置可先画方向射线再取距离，也可先定距离圆弧再定方向。','清凉岛在O南偏西40°方向20千米处，图上1厘米代表10千米。请操作定位并记录。',[num('图上距离',2,'厘米'),num('南向西偏角',40,'度')],'先从南方向朝西偏40°，沿射线取2厘米。O是唯一观测点；距离不能从画布边缘量。',['南偏西位于左下象限。','20÷10得到图上厘米数。'],params={'col':3,'row':4,'quadrant':0,'angle':30,'distance':10},construction={'quadrant':3,'angle':40,'distance':20})
add('U7-04','position','综合定位把数对路线、方向距离和观测点转换分开。','路线（6，2）到（9，2）再到（9，4）；另把北偏东30°方向30千米目标反向描述回O。',[num('先向东走的格数',3,'格'),num('再向北走的格数',2,'格'),choice('从目标看O的方向',['北偏东30°','南偏西30°','南偏东30°'],1,'交换观测点后方向相反，角度不变。')],'列增3表示向东3格，行增2表示向北2格；相反方向为南偏西30°，距离仍30千米。',['每一步只看变化的那一项。','反向观察要换起始南北与东西。'],variant='grid',params={'col':6,'row':2,'quadrant':0,'angle':30,'distance':30})
add('U7-05','position','反思要指出表示方法的条件与局限。','保存同一位置的方格数对与方向距离记录，比较两种方法需要哪些信息。',[],'说明原点/观测点、轴方向、比例尺，提出一次误差检查；不要记录真实家庭位置。',['数对需要统一格距与坐标约定。','方向距离需要统一观测点和单位。'],params={'col':3,'row':4,'quadrant':0,'angle':30,'distance':20})
# End-of-term linked review; mixed family per named learning position.
add('R-01','place','数与运算复习把意义和计数单位联系，而不是只背口诀。','将0.6×0.7、0.21÷0.3、0.12÷3/4用计数单位或逆运算解释。',[num('0.6×0.7','0.42'),num('0.21÷0.3','0.7'),num('0.12÷3/4','0.16')],'乘法为42个百分之一；除法同单位转化；除以3/4等于乘4/3。',['可以把0.12写成12/100。','用答案乘除数检验。'],variant='decimal',params={'count':42,'denominator':100})
add('R-02','relation','数量关系复习要先辨单位“1”，再区分总量、部分与效率。','60平方米菜地先用20平方米，余下2/5种黄瓜；4.5小时阅读再增加2/9。',[num('黄瓜面积',16,'平方米'),num('增加后的阅读时间','5.5','小时')],'黄瓜是(60−20)×2/5；阅读为4.5×(1+2/9)。两个分率所依据的整体不同。',['标出“余下的”四个字。','把“多”转换为1加该分率。'],params={'total':40,'part':2,'den':5})
add('R-03','circle','圆复习同时检查r、d、C、S的单位与关系，不能把长度当面积。','半径3分米的圆，求直径、周长、面积（π取3.14）。',[num('直径',6,'分米'),num('周长','18.84','分米'),num('面积','28.26','平方分米')],'d=2r；C=2πr；S=πr²。面积的单位是平方分米，不能写分米。',['先列出已知r。','每个公式带上量的意义与单位。'],params={'radius':3,'angle':360,'slices':16,'assembled':1})
add('R-04','scale','图形运动复习区分放缩、平移、旋转；对应关系比外观更可靠。','按2∶1放大底3格高2格梯形，再看平移7格是否改变面积。',[num('新底',6,'格'),num('新高',4,'格'),choice('平移是否改变面积',['改变','不改变'],1,'平移改变位置，不改变形状和大小。')],'放缩边长乘2、面积乘4；平移只对坐标加同一个位移。两种操作不同。',['比较每一条对应边。','平移后各点的相对距离保持。'],params={'sx':2,'sy':2,'divisor':1})
add('R-05','decimal','运算复习同时检查估计范围、运算顺序和近似精度。','3.7×0.46、2.4÷0.26均保留两位小数，再算0.36+9.6÷3.2。',[num('3.7×0.46近似值','1.70'),num('2.4÷0.26近似值','9.23'),num('混合算式结果','3.36')],'准确积1.702；商9.230769…；先除得3再加0.36。1.7与1.70数值相同，本题界面仍应理解精确到百分位的要求。',['先估计数量级。','舍入只在最后要求的位置做。'],params={'a':370,'b':46})
add('R-06','relation','综合应用区分按总量分配、已知部分反求总量、合作效率。','0.78公顷按5∶1分水田旱地；两人8小时、10小时单独整理同批书。',[num('水田面积','0.65','公顷'),num('旱地面积','0.13','公顷'),num('合做时间','40/9','小时')],'总份数6，每份0.13；合作效率1/8+1/10=9/40，总时间40/9小时。不能把两个时间平均。',['先确定0.78是总量。','工程总量可设1。'],variant='work',params={'first':8,'second':10,'elapsed':1})
add('R-07','circle','圆、坐标与放缩综合练习保持各自的约定。','在（4，3）处半径2格圆中作面积占1/4的扇形；直径45厘米车轮滚40圈（π取3.14）。',[num('扇形圆心角',90,'度'),num('车轮滚过长度','56.52','米')],'四分之一圆对应90°；每圈3.14×45厘米，40圈共5652厘米=56.52米。坐标只表示圆心位置。',['面积占比在同一个圆中比较。','先算厘米路程，最后换米。'],params={'radius':2,'angle':90,'slices':16,'assembled':0})
add('R-08','position','地图比例尺与网格变换应分步处理：先统一单位，再按坐标规则移动。','1∶1000000图上表示173千米；点（9，2）向左移7格；绕原点旋转的角与长度分开比较。',[num('173千米的图上距离','17.3','厘米'),num('平移后的列',2),num('平移后的行',2)],'173千米=17300000厘米，除1000000得17.3厘米；列减7、行不变。旋转不同于平移。',['千米到厘米要乘100000。','向左移动影响第一项。'],variant='grid',params={'col':9,'row':2,'quadrant':0,'angle':30,'distance':20})
add('R-09','ratio','探索的规律需要说明适用条件，再用新例检验；颜色混合还需实际材料验证。','比较1/2−1/3与1/2×1/3；三堆各60枚棋子，第一堆1/3白子，第二堆黑子与第三堆白子相等。',[num('1/2−1/3','1/6'),num('1/2×1/3','1/6'),num('三堆白子总数',80,'枚')],'第二堆白子=60−第二堆黑子=60−第三堆白子，因此后二堆白子共60，连第一堆20得80。倒数差与积相等在相邻正整数倒数时成立，不能随意推广。',['把第二、第三堆合起来找不变量。','选择1/4与1/5检验倒数关系。'],params={'first':1,'second':2,'scale':1})
add('R-10','relation','全册反思应有具体证据和可执行的补缺计划，完成课表不等于掌握。','选一条自己保存的模型记录，写“已理解的一点、仍不足的一点、下一步怎样验证”。可选择调配颜色、设计贺卡等实践，不填真实个人信息。',[],'引用具体数量或图形关系，区别观察、推测与有规则的核对；为自己选一个下一次练习目标。',['可以从数位、整体、单位、对应边、观测点中选一项。','改进计划写成可做的一步，而不是“更认真”。'],params={'total':60,'part':1,'den':3})
